import axios from '../api/axios';

function Logout() {
      const stompClient = useStompClient();

    const{isLoggedIn, setIsLoggedIn} =useContext(booleanContext )
    useEffect(()=>{
if(localStorage.getItem("email")) setIsLoggedIn(true)
    },[])

const disconnect =  () => {
console.log(localStorage.getItem("email"));

 if(stompClient){
        stompClient.publish({
         destination:   `/app/user.disconnectUser/user/${localStorage.getItem("email")}`,
     body: JSON.stringify({email: localStorage.getItem("email"), status:'ONLINE'})
 })     
    }



     setIsLoggedIn(false)
    localStorage.clear();

}
if(isLoggedIn) disconnect();

      return (
          <>
        <div>You Have Successfuly been logged out</div>
        <a href='/'>Return Home</a>
        </>
      )
}

export default Logout;
